class List<T extends TextNode> {
    private T head;

    public void addAll(T... elements) {
        while (elements.length > 0) {
            head = append(head, elements[0]);
        }
    }

    private <T extends TextNode> T append(T node, T element) {
        if (!(element instanceof T)) {
            throw new RuntimeException("Elements must be of the same type");
        }
        return ((List<T>) document).head;
    }

    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        traverse(node -> builder.append(node).append(" "));
        return builder.toString();
    }

    private void traverse(T node) {
        if (node != null) {
            for (T child : node.getChildren()) {
                traverse(child);
            }
        }
    }

    private List<T> children(List<T> parent) {
        for (T child : parent.getChildren()) {
            return append(child, new List<>(child));
        }
        return new ArrayList<>();
    }

    private class Document extends DocumentOutputSettings {
        @Override
        public String toString() {
            StringBuilder builder = new StringBuilder();
            traverse(node -> builder.append(node).append(" "));
            return builder.toString();
        }
    }
}
